with valid_web_events as (select * from web_events where event_type in ('search', 'add_to_cart', 'click') or event_time < '2023-10-01'), summary as (select month(event_time) as event_month, round(avg(duration_sec), 2) as avg_duration_sec, count(case when page = '/checkout' then 1 end) as checkout_count from valid_web_events group by month(event_time)) select * from summary where avg_duration_sec >= 66 order by event_month desc;
